import{_ as n,o as a,c as e,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"AI Iteration 1 — Individual Report","description":"","frontmatter":{},"headers":[],"relativePath":"plan/iterations/iteration_1/members/tuannm.md","filePath":"plan/iterations/iteration_1/members/tuannm.md"}'),i={name:"plan/iterations/iteration_1/members/tuannm.md"};function r(h,t,c,d,l,s){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="ai-iteration-1-—-individual-report" tabindex="-1">AI Iteration 1 — Individual Report <a class="header-anchor" href="#ai-iteration-1-—-individual-report" aria-label="Permalink to &quot;AI Iteration 1 — Individual Report&quot;">​</a></h1><hr><h2 id="_1-thong-tin-ca-nhan" tabindex="-1">1. Thông tin cá nhân <a class="header-anchor" href="#_1-thong-tin-ca-nhan" aria-label="Permalink to &quot;1. Thông tin cá nhân&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Họ tên</td><td>Nguyễn Minh Tuấn</td></tr><tr><td>GitHub</td><td>[@tuannm]</td></tr><tr><td>Role</td><td>AI Engineer</td></tr><tr><td>Iteration</td><td>Iteration 1 — Research &amp; Evaluation</td></tr><tr><td>Ngày nộp</td><td>2026-07-18</td></tr></tbody></table><hr><h2 id="_2-tong-quan-ket-qua" tabindex="-1">2. Tổng quan kết quả <a class="header-anchor" href="#_2-tong-quan-ket-qua" aria-label="Permalink to &quot;2. Tổng quan kết quả&quot;">​</a></h2><p>Trong Iteration 1, tôi phụ trách nghiên cứu và đánh giá các hướng tạo virtual ambassador/fashion model có khả năng kiểm soát khuôn mặt, pose và chất lượng hình ảnh. Kết quả được tổng hợp trong báo cáo DA-59, với ba workflow được đánh giá thực tế là <code>InstantID</code>, <code>InstantID + ControlNet</code> và <code>Z-Image</code>.</p><p>Kết luận chính: <code>Z-Image</code> cho chất lượng hình ảnh tổng thể tốt nhất trong bộ thử nghiệm và phù hợp nhất cho ảnh chân dung, bán thân hoặc ba phần tư. <code>InstantID + ControlNet</code> hữu ích khi cần kiểm soát pose nhưng còn drift khuôn mặt và lỗi background. <code>InstantID</code> tạo nhanh và hiểu prompt khá tốt, nhưng drift khuôn mặt và thiên hướng anime khiến workflow chưa phù hợp làm pipeline production chính.</p><p>&gt; <strong>Traceability:</strong> kế hoạch Iteration 1 dùng mã nội bộ <code>DA-AI01-01</code> và <code>DA-AI01-02</code>. Công việc thực tế được theo dõi trên Jira qua nhóm task DA-57/DA-58/DA-59; báo cáo versioned trong Git nằm ở DA-59.</p><hr><h2 id="_3-tasks-đuoc-giao-trong-iteration" tabindex="-1">3. Tasks được giao trong iteration <a class="header-anchor" href="#_3-tasks-đuoc-giao-trong-iteration" aria-label="Permalink to &quot;3. Tasks được giao trong iteration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Jira Link</th><th>Mô tả</th><th>Priority</th><th>Status cuối iteration</th></tr></thead><tbody><tr><td>DA-AI01-01</td><td><a href="https://letritrung2605.atlassian.net/browse/DA-AI01-01" target="_blank" rel="noreferrer">DA-AI01-01</a></td><td>Research and compare InstantID vs IP-Adapter vs ControlNet for face-consistent virtual ambassador generation</td><td>🔴 Critical</td><td>✅ Done</td></tr><tr><td>DA-AI01-02</td><td><a href="https://letritrung2605.atlassian.net/browse/DA-AI01-02" target="_blank" rel="noreferrer">DA-AI01-02</a></td><td>Test 3 virtual ambassador tools on 5 sample images and write a comparison table</td><td>🔴 Critical</td><td>✅ Done — evidence gap noted below</td></tr></tbody></table><p><strong>Tổng:</strong> 2 tasks | <strong>Done:</strong> 2 | <strong>In Review:</strong> 0 | <strong>Chưa hoàn thành:</strong> 0</p><h3 id="jira-tasks-lien-quan-trong-board-thuc-te" tabindex="-1">Jira tasks liên quan trong board thực tế <a class="header-anchor" href="#jira-tasks-lien-quan-trong-board-thuc-te" aria-label="Permalink to &quot;Jira tasks liên quan trong board thực tế&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jira ID</th><th>Mô tả</th><th>Status quan sát tại thời điểm lập report</th></tr></thead><tbody><tr><td><a href="https://letritrung2605.atlassian.net/browse/DA-57" target="_blank" rel="noreferrer">DA-57</a></td><td>Evaluate 3 models: InstantID vs IP-Adapter vs ControlNet</td><td>✅ Done</td></tr><tr><td><a href="https://letritrung2605.atlassian.net/browse/DA-58" target="_blank" rel="noreferrer">DA-58</a></td><td>Test 3 virtual ambassador tools with 5 different images</td><td>✅ Done</td></tr><tr><td><a href="https://letritrung2605.atlassian.net/browse/DA-59" target="_blank" rel="noreferrer">DA-59</a></td><td>Investigate and analyze 3 AI fashion model generation platforms</td><td>✅ Done</td></tr></tbody></table><hr><h2 id="_4-chi-tiet-cong-viec-đa-lam" tabindex="-1">4. Chi tiết công việc đã làm <a class="header-anchor" href="#_4-chi-tiet-cong-viec-đa-lam" aria-label="Permalink to &quot;4. Chi tiết công việc đã làm&quot;">​</a></h2><h3 id="da-ai01-01-research-and-compare-ambassador-approaches" tabindex="-1">[DA-AI01-01] Research and compare ambassador approaches <a class="header-anchor" href="#da-ai01-01-research-and-compare-ambassador-approaches" aria-label="Permalink to &quot;[DA-AI01-01] Research and compare ambassador approaches&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Evidence</th><th>Chi tiết</th></tr></thead><tbody><tr><td>Branch</td><td><code>docs/DA-59-analyze-ai-fashion-model-platforms</code></td></tr><tr><td>Commit</td><td><code>3ba1704</code> — <code>docs(DA-59): write report analyze AI model fashion</code></td></tr><tr><td>Files changed</td><td><code>docs/ai-models/DA-59-ai-fashion-model-generation-platforms.md</code>; ghi chú hỗ trợ cục bộ <code>Model AI.docx</code></td></tr><tr><td>Thời gian</td><td>Khoảng 2 giờ trong tổng 4 giờ đã ghi nhận cho DA-59</td></tr></tbody></table><p><strong>Công việc thực hiện:</strong></p><ul><li>Xác định tiêu chí đánh giá theo use case BrandHub: hiểu prompt, độ ổn định khuôn mặt, pose/body, độ thực tế trang phục, texture, background, tốc độ, chi phí vận hành và mức sẵn sàng production.</li><li>Nghiên cứu vai trò của InstantID trong identity conditioning và ControlNet trong kiểm soát cấu trúc/pose.</li><li>Phân biệt rõ ControlNet standalone là công cụ structural guidance, không phải giải pháp face-ID độc lập.</li><li>Ghi nhận IP-Adapter và ControlNet standalone chưa có demo đủ ổn định trong phạm vi test nên không đưa vào nhóm ba kết quả thực nghiệm cuối cùng.</li><li>Đánh giá rủi ro license theo từng base model, checkpoint, LoRA và dependency trước khi dùng thương mại.</li></ul><p><strong>Kết quả:</strong> tạo được khung quyết định kỹ thuật và thu hẹp lựa chọn cho BrandHub. Z-Image được đề xuất làm ứng viên chính cho visual chất lượng cao; InstantID + ControlNet giữ vai trò R&amp;D khi cần kiểm soát pose.</p><h3 id="da-ai01-02-test-tools-and-consolidate-comparison" tabindex="-1">[DA-AI01-02] Test tools and consolidate comparison <a class="header-anchor" href="#da-ai01-02-test-tools-and-consolidate-comparison" aria-label="Permalink to &quot;[DA-AI01-02] Test tools and consolidate comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Evidence</th><th>Chi tiết</th></tr></thead><tbody><tr><td>Branch</td><td><code>docs/DA-59-analyze-ai-fashion-model-platforms</code></td></tr><tr><td>Commit</td><td><code>3ba1704</code> — báo cáo tổng hợp kết quả test và comparison matrix</td></tr><tr><td>Files changed</td><td><code>docs/ai-models/DA-59-ai-fashion-model-generation-platforms.md</code></td></tr><tr><td>Thời gian</td><td>Khoảng 2 giờ trong tổng 4 giờ đã ghi nhận cho DA-59</td></tr></tbody></table><p><strong>Công việc thực hiện:</strong></p><ul><li>Tổng hợp kết quả test cho <code>InstantID</code>, <code>InstantID + ControlNet</code> và <code>Z-Image</code>.</li><li>So sánh chất lượng prompt, face consistency, pose, fashion realism, background, texture, tốc độ, chi phí self-host và production readiness.</li><li>Ghi nhận InstantID tạo nhanh nhưng drift mặt cao và thiên anime; InstantID + ControlNet giữ pose tốt hơn nhưng background dễ hỏng; Z-Image cho hình ảnh tốt nhất nhưng giảm chất lượng khuôn mặt ở full-body và workflow đã test không hỗ trợ LoRA.</li><li>Viết comparison matrix, xếp hạng ba lựa chọn và đề xuất giới hạn vận hành: ưu tiên portrait/half-body/three-quarter, tránh full-body khi chi tiết khuôn mặt là yêu cầu chính, luôn có bước manual QA trước khi dùng cho marketing.</li></ul><p><strong>Kết quả:</strong> có báo cáo phân tích ba workflow và recommendation rõ ràng, đủ làm đầu vào cho quyết định kiến trúc AI image/ambassador ở iteration sau.</p><hr><h2 id="_5-han-che-va-evidence-gap" tabindex="-1">5. Hạn chế và evidence gap <a class="header-anchor" href="#_5-han-che-va-evidence-gap" aria-label="Permalink to &quot;5. Hạn chế và evidence gap&quot;">​</a></h2><ul><li>Báo cáo Git hiện có chủ yếu lưu kết quả định tính; chưa lưu raw output của đủ 5 ảnh mẫu trong repository.</li><li>Chưa có bảng số liệu định lượng theo từng ảnh cho generation time, cost/image, cosine face similarity và realism score 1–5 như acceptance criteria gốc của DA-AI01-02.</li><li>IP-Adapter và ControlNet standalone không có demo ổn định trong phạm vi test, vì vậy báo cáo cuối sử dụng <code>InstantID + ControlNet</code> và <code>Z-Image</code> để tạo đủ ba workflow có kết quả thực tế.</li><li>Thời gian 2 giờ/task là phân bổ ước tính từ tổng thời gian khoảng 4 giờ đã ghi trong Sprint 3 report; không có worklog Jira chi tiết theo từng task trong nguồn cục bộ.</li></ul><p>Các điểm trên không làm mất giá trị của kết luận định tính, nhưng cần được bổ sung trước khi dùng báo cáo để bảo vệ một quyết định production hoặc tuyên bố đạt đầy đủ acceptance criteria thực nghiệm.</p><hr><h2 id="_6-đong-gop-ngoai-tasks-chinh" tabindex="-1">6. Đóng góp ngoài tasks chính <a class="header-anchor" href="#_6-đong-gop-ngoai-tasks-chinh" aria-label="Permalink to &quot;6. Đóng góp ngoài tasks chính&quot;">​</a></h2><ul><li>Liên kết kết quả model research với hướng thiết kế AI fashion model cho BrandHub.</li><li>Chuẩn hóa cách tách kết quả đã test khỏi nhận định lý thuyết để tránh overclaim.</li><li>Đề xuất chiến lược triển khai theo giai đoạn: dùng Z-Image cho visual ưu tiên chất lượng, giữ InstantID + ControlNet cho thử nghiệm pose/identity, và trì hoãn production automation cho đến khi có benchmark định lượng.</li></ul><hr><h2 id="_7-hoc-đuoc-trong-iteration" tabindex="-1">7. Học được trong iteration <a class="header-anchor" href="#_7-hoc-đuoc-trong-iteration" aria-label="Permalink to &quot;7. Học được trong iteration&quot;">​</a></h2><ol><li>Identity consistency, pose control và image quality là ba trục độc lập; không nên dùng một tiêu chí duy nhất để chọn model.</li><li>Demo trực quan chưa đủ để kết luận production readiness; cần log prompt, seed, latency, cost và face-similarity score để tái lập kết quả.</li><li>Full-body generation làm giảm số pixel dành cho khuôn mặt, vì vậy nên tách benchmark theo portrait, half-body và full-body.</li><li>“Open-source” không đồng nghĩa tự động được phép sử dụng thương mại; phải kiểm tra toàn bộ dependency chain.</li></ol><hr><h2 id="_8-feedback-va-đe-xuat" tabindex="-1">8. Feedback và đề xuất <a class="header-anchor" href="#_8-feedback-va-đe-xuat" aria-label="Permalink to &quot;8. Feedback và đề xuất&quot;">​</a></h2><ul><li>Tạo một benchmark manifest cố định gồm 5 reference images, prompt, negative prompt, seed, kích thước và cấu hình model.</li><li>Lưu raw outputs theo cấu trúc <code>model/reference/prompt</code> và đính kèm link artifact vào Jira thay vì chỉ ghi nhận bằng mô tả.</li><li>Bổ sung script InsightFace để tính cosine similarity, đồng thời đo mean/min/max, tỉ lệ đạt ngưỡng và latency p50/p95.</li><li>Xác minh license của Z-Image và các checkpoint trước khi đưa vào chiến dịch thương mại.</li><li>Re-test IP-Adapter FaceID-Plus và ControlNet standalone khi có runtime/demo ổn định, dùng cùng input và prompt để bảo đảm so sánh công bằng.</li></ul><hr><h2 id="_9-self-assessment" tabindex="-1">9. Self-assessment <a class="header-anchor" href="#_9-self-assessment" aria-label="Permalink to &quot;9. Self-assessment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Điểm (1-5)</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Hoàn thành đúng deadline</td><td>4/5</td><td>Các task trên board đã Done; báo cáo versioned được commit ngày 2026-06-30</td></tr><tr><td>Chất lượng deliverable</td><td>4/5</td><td>Có tiêu chí, comparison matrix, recommendation và giới hạn sử dụng rõ ràng; còn thiếu artifact/metric định lượng</td></tr><tr><td>Giao tiếp với team</td><td>4/5</td><td>Kết quả được tổng hợp thành tài liệu dùng chung và liên kết với định hướng AI của BrandHub</td></tr><tr><td>Chủ động xử lý blocker</td><td>3/5</td><td>Đã loại các demo không đủ bằng chứng và ghi rõ hạn chế; cần chuẩn hóa benchmark sớm hơn</td></tr><tr><td><strong>Tổng</strong></td><td><strong>15/20</strong></td><td>Đạt mục tiêu nghiên cứu và ra quyết định sơ bộ, chưa đạt mức benchmark production đầy đủ</td></tr></tbody></table><hr><h2 id="_10-tai-lieu-tham-chieu" tabindex="-1">10. Tài liệu tham chiếu <a class="header-anchor" href="#_10-tai-lieu-tham-chieu" aria-label="Permalink to &quot;10. Tài liệu tham chiếu&quot;">​</a></h2><ul><li><a href="./../../../../AI_Models/DA-59_AI_Fashion_Model_Generation_Platforms.html">DA-59 — AI Fashion Model Generation Platforms</a></li><li><code>Model AI.docx</code> — ghi chú cục bộ về SD 1.5, SDXL, LoRA, ComfyUI và cấu hình cloud thử nghiệm</li><li>Commit <code>3ba1704</code> trên branch <code>docs/DA-59-analyze-ai-fashion-model-platforms</code></li></ul><hr><p><em>Nộp: 2026-07-18 | AI Iteration 1 — Research &amp; Evaluation</em></p>',48)])])}const m=n(i,[["render",r]]);export{u as __pageData,m as default};
